    help: {
      dash: { title: 'Vue d\'ensemble de la plateforme', body: 'Chaque organisation inscrite sur Paxve, comptée selon sa situation : en essai, active (payée), en délai de grâce (la date est passée mais elle peut encore travailler quelques jours), expirée (consultation et export seulement) et bloquée (personne ne peut se connecter).\n\nLe revenu mensuel additionne le prix mensuel de chaque organisation active ou en délai de grâce ; les formules annuelles comptent pour un douzième. Cliquez sur une case pour ouvrir la liste.' },
      orgs: { title: 'Organisations', body: 'Filtrez par situation, formule ou pays, ou cherchez. Clic droit sur la grille pour exporter vers Excel / CSV.\n\nChoisissez une organisation pour voir ses utilisateurs, sociétés, usage, paiements et l\'historique de chaque action. Renouveler enregistre un paiement et prolonge la date payé jusqu\'au. Bloquer empêche toute connexion et affiche votre motif. Le mode support ouvre l\'organisation comme son administrateur, en lecture seule, avec un bandeau violet ; fermez-le depuis le bandeau.' },
      requests: { title: 'Demandes de renouvellement', body: 'Les organisations demandent un renouvellement ou un changement de formule depuis Paramètres → Mon abonnement Paxve, souvent avec une référence de transfert Whish / OMT. Vérifiez la réception, puis renouvelez depuis la demande : le paiement est enregistré et la demande fermée.' },
      payments: { title: 'Paiements reçus', body: 'Chaque paiement enregistré lors d\'un renouvellement, avec la période couverte. Les totaux par devise sont affichés en haut.' },
      plans: { title: 'Formules et prix', body: 'Prix par mois et par an, et limites de chaque formule (abonnements actifs, utilisateurs, sociétés ; vide = illimité). Une limite modifiée s\'applique aux nouvelles organisations et aux renouvellements ; cochez « appliquer aussi » pour mettre à jour les organisations déjà sur la formule.' },
    },
    sum: { orgs: '{{n}} organisations', requests: '{{n}} demandes ouvertes' },
    allApps: "Toutes les applications", gf: { apps: "Applications de la formule", kept: "Applications conservées", remove: "Retirer les applications conservées", hint: "Elles étaient utilisées quand la liste des applications de la formule a été réduite : l'organisation les garde. Retirez-les pour appliquer la formule telle quelle.", count: "{{n}} organisations gardent des applications déjà utilisées", planHint: "Les organisations qui utilisent déjà une application que vous décochez la gardent (affichée comme application conservée dans leur résumé)." },
    jobs: { paused: "tâches automatiques suspendues", resumed: "tâches automatiques reprises", hint: "Tant qu'elle est expirée ou bloquée, rien ne tourne tout seul pour cette organisation (facturation, relances, écritures récurrentes, messages, coupure/rétablissement internet, webhooks). Le travail en attente part après un renouvellement ou un déblocage." },
